import java.util.*;

class MinStack {
    private List<Integer> list;

    public MinStack() {
        list = new ArrayList<>();
    }

    public void push(int value) {
        list.add(value);
    }

    public void pop() {
        list.remove(list.size() - 1);
    }

    public int top() {
        return list.get(list.size() - 1);
    }

    public int getMin() {
        int mn = list.get(0);
        for (int v : list) if (v < mn) mn = v;   // 每次都要全扫，O(n)
        return mn;
    }
}

import java.util.*;

class MinStack {
    private Deque<Integer> data;
    private Deque<Integer> mins;   // mins 第 i 个 = data 前 i+1 个的最小值

    public MinStack() {
        data = new ArrayDeque<>();
        mins = new ArrayDeque<>();
    }

    public void push(int value) {
        data.push(value);
        // 辅助栈同步压入「当前最小值」
        mins.push(mins.isEmpty() ? value : Math.min(value, mins.peek()));
    }

    public void pop() {
        data.pop();
        mins.pop();   // 同步弹出，不需要任何分支判断
    }

    public int top() {
        return data.peek();
    }

    public int getMin() {
        return mins.peek();
    }
}

import java.util.*;

class MinStack {
    private Deque<Integer> data;
    private Deque<Integer> mins;   // 只存历史最低点，单调不增

    public MinStack() {
        data = new ArrayDeque<>();
        mins = new ArrayDeque<>();
    }

    public void push(int value) {
        data.push(value);
        // 必须用 <= ：相等的值也要入栈，否则 pop 时数量对不上
        if (mins.isEmpty() || value <= mins.peek()) {
            mins.push(value);
        }
    }

    public void pop() {
        int v = data.pop();
        // 弹走的正是当前最小值，辅助栈才跟着弹
        if (!mins.isEmpty() && v == mins.peek()) {
            mins.pop();
        }
    }

    public int top() {
        return data.peek();
    }

    public int getMin() {
        return mins.peek();
    }
}
